insert into public.trails (slug, name, region, distance_miles, elevation_gain_ft, summit_elevation_ft, difficulty, est_time, trailhead, description, is_six_pack, image_url, image_credit) values
  ('mt-wilson', 'Mt. Wilson via Chantry Flat', 'San Gabriel Mountains', 14, 4300, 5710, 'Hard', '7-9 hours', 'Chantry Flat, Arcadia', 'The classic Six-Pack warm-up climbs out of a shady canyon past Sturtevant Falls, then switchbacks up to the observatory ridge. Expect creek crossings, old cabins, and a big view over the LA basin from the top.', true, 'assets/img/trails/mt-wilson.jpg', 'Photo: Grigory Heaton, CC BY-SA 4.0'),
  ('cucamonga-peak', 'Cucamonga Peak via Icehouse Canyon', 'San Gabriel Mountains', 10, 4300, 8859, 'Strenuous', '6-8 hours', 'Icehouse Canyon, Mt. Baldy Road', 'A steady climb through pines and cedars to Icehouse Saddle, followed by a rocky ridge push to a summit that overlooks the whole Inland Empire. It is steep and sunny near the top, so start early.', true, 'assets/img/trails/cucamonga-peak.jpg', 'Photo: Mk1Mod0, Public domain'),
  ('mt-baldy', 'Mt. Baldy (Mt. San Antonio) via Ski Hut Trail', 'San Gabriel Mountains', 11, 3900, 10064, 'Strenuous', '6-8 hours', 'Manker Flat, Mt. Baldy Village', 'The highest point in LA County rewards you with a bare, wind-scoured summit. Most hikers go up the Ski Hut Trail and return over the exposed Devil''s Backbone ridge for a loop with sweeping views.', true, 'assets/img/trails/mt-baldy.jpg', 'Photo: Eric T Gunther, CC BY-SA 3.0'),
  ('san-bernardino-peak', 'San Bernardino Peak via Angelus Oaks', 'San Bernardino Mountains', 16, 4700, 10649, 'Strenuous', '9-11 hours', 'Angelus Oaks (Forest Falls Rd area)', 'A long, steady ridge walk with a string of false summits and few water sources. The payoff is a quiet, high-alpine peak with views toward San Gorgonio and out to the desert.', true, 'assets/img/trails/san-bernardino-peak.jpg', 'Photo: The Fun Chronicles, CC0'),
  ('san-jacinto-peak', 'San Jacinto Peak via Marion Mountain', 'San Jacinto Mountains', 11, 4500, 10834, 'Strenuous', '7-9 hours', 'Marion Mountain Trailhead, Idyllwild', 'A relentless forested climb that joins the Deer Springs trail before the final granite scramble to the stone hut on top. On a clear day you can see the desert floor nearly two miles below.', true, 'assets/img/trails/san-jacinto-peak.jpg', 'Photo: Kit Conn, CC BY-SA 3.0'),
  ('san-gorgonio-mountain', 'San Gorgonio Mountain via Vivian Creek', 'San Bernardino Mountains', 17, 5800, 11503, 'Strenuous', '10-12 hours', 'Vivian Creek Trailhead, Forest Falls', 'The tallest peak in Southern California is a big day: a steep climb through forest, a long traverse above tree line, and a broad, rocky summit plateau. Permits are required and altitude catches many hikers off guard.', true, 'assets/img/trails/san-gorgonio-mountain.jpg', 'Photo: Joshua Tree National Park, Public domain'),
  ('cowles-mountain', 'Cowles Mountain', 'San Diego County', 3, 950, 1593, 'Easy', '1.5-2 hours', 'Barker Way, San Carlos', 'San Diego''s most popular short hike climbs a wide trail to the highest point in the city. The summit has a 360-degree view of downtown, the coast, and the backcountry, and it is especially good at sunset.', false, 'assets/img/trails/cowles-mountain.jpg', 'Photo: Pattymooney, CC BY-SA 3.0'),
  ('mt-woodson', 'Mt. Woodson (Potato Chip Rock)', 'San Diego County', 7.5, 2100, 2894, 'Moderate', '4-5 hours', 'Lake Poway Recreation Area', 'A sunny trail through granite boulders leads to a thin flake of rock that is famous for photos. Go on a weekday morning to skip the line, and carry plenty of water because there is little shade.', false, 'assets/img/trails/mt-woodson.jpg', 'Photo: chrisinphilly5448, CC BY-SA 2.0'),
  ('iron-mountain', 'Iron Mountain', 'San Diego County', 6, 1100, 2696, 'Moderate', '3-3.5 hours', 'Ellie Lane, Poway', 'A well-graded path rolls through chaparral and oaks to a summit marker with views from the ocean to the mountains. It is less crowded than its neighbors and a good choice for a first real San Diego summit.', false, 'assets/img/trails/iron-mountain.jpg', 'Photo: The Fun Chronicles, CC0')
